//!/lib-groovy/v4
import groovy.json.JsonSlurper
import javax.net.ssl.HostnameVerifier
import javax.net.ssl.HttpsURLConnection
import javax.net.ssl.SSLContext
import javax.net.ssl.SSLSession
import javax.net.ssl.TrustManager
import javax.net.ssl.X509TrustManager
import java.security.cert.X509Certificate
def pveProps = binding.hasVariable('netscanProps') ? netscanProps
             : binding.hasVariable('hostProps') ? hostProps : [:]
def pveHostProp = { String key, String fallback = null ->
    def value = pveProps.get(key)
    (value == null || value.toString().trim().isEmpty()) ? fallback : value.toString().trim()
}
def pveBaseUrl = pveHostProp('pve.api.url')
if (!pveBaseUrl) {
    def hostname = pveHostProp('system.hostname')
    if (hostname) {
        pveBaseUrl = 'https://' + hostname + ':' + pveHostProp('pve.api.port', '8006')
    }
}
def pveToken = pveHostProp('pve.token.credential')
def pveTimeout = pveHostProp('pve.api.timeout', '10000') as int
def pveConfigError = null
if (!pveBaseUrl) {
    pveConfigError = 'Cannot determine the Proxmox API URL: set pve.api.url, or ensure system.hostname resolves.'
} else if (!pveToken) {
    pveConfigError = 'Missing pve.token.credential. Expected the full token string: user@realm!tokenid=secret'
}
if (pveHostProp('pve.api.insecure', 'false').toBoolean()) {
    def trustAll = [
        getAcceptedIssuers: { -> new X509Certificate[0] },
        checkClientTrusted: { X509Certificate[] certs, String authType -> },
        checkServerTrusted: { X509Certificate[] certs, String authType -> }
    ] as X509TrustManager
    def sslContext = SSLContext.getInstance('TLS')
    sslContext.init(null, [trustAll] as TrustManager[], new java.security.SecureRandom())
    HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory())
    HttpsURLConnection.setDefaultHostnameVerifier({ String hostname, SSLSession session -> true } as HostnameVerifier)
}
def pveUrlScheme = { -> pveBaseUrl ? (new URI(pveBaseUrl).scheme ?: 'https') : 'https' }
def pveUrlPort = { ->
    def port = pveBaseUrl ? new URI(pveBaseUrl).port : -1
    port > 0 ? port : (pveHostProp('pve.api.port', '8006') as int)
}
def pveHostUrl = { String host ->
    def address = host?.trim()
    if (!address) { return null }
    if (address.contains('://')) { return address.replaceAll('(/api2/json)?/*$', '') }
    def prefix = pveUrlScheme() + '://'
    if (address.startsWith('[')) { return prefix + (address.contains(']:') ? address : address + ':' + pveUrlPort()) }
    if (address.count(':') > 1) { return prefix + '[' + address + ']:' + pveUrlPort() }
    if (address.contains(':')) { return prefix + address }
    return prefix + address + ':' + pveUrlPort()
}
def pveApiBases = { ->
    def own = pveHostProp('pve.node') ? pveHostUrl(pveHostProp('system.hostname')) : null
    ([own, pveBaseUrl?.replaceAll('/+$', '')] +
        pveHostProp('pve.api.hosts', '').tokenize(',').collect { pveHostUrl(it) })
        .findAll { it }.unique()
}
def pveGetAt = { String base, String path ->
    def connection = new URL(base.replaceAll('/+$', '') + '/api2/json' + path).openConnection()
    connection.setRequestMethod('GET')
    connection.setConnectTimeout(pveTimeout)
    connection.setReadTimeout(pveTimeout)
    connection.setRequestProperty('Authorization', 'PVEAPIToken=' + pveToken)
    connection.setRequestProperty('Accept', 'application/json')
    int status = connection.responseCode
    if (status == 401) {
        throw new IOException('HTTP 401 for ' + path +
            ' - the API token in pve.token.credential was rejected. Check its secret, and that it has a' +
            ' PVEAuditor ACL. A token with privilege separation enabled needs its own ACL entry,' +
            ' not just the one on its user.')
    }
    if (status == 403) {
        throw new IOException('HTTP 403 for ' + path + ' (' + connection.responseMessage + ')' +
            ' - the token in pve.token.credential lacks that privilege. The suite needs PVEAuditor on /.')
    }
    if (status < 200 || status >= 300) {
        throw new IOException('HTTP ' + status + ' for ' + path)
    }
    def payload = new JsonSlurper().parse(connection.inputStream)
    connection.disconnect()
    return payload?.data
}
def pveFailureStatus = { Exception failure ->
    def match = failure.message =~ /^HTTP (\d+) /
    match.find() ? (match.group(1) as int) : null
}
def pveActiveBase = null
def pveBasesFor = { String path ->
    def bases = pveApiBases()
    if (pveActiveBase in bases) { bases = [pveActiveBase] + (bases - pveActiveBase) }
    path.startsWith('/nodes/') ? bases.take(2) : bases
}
def pveGet = { String path ->
    def bases = pveBasesFor(path)
    Exception last = null
    for (base in bases) {
        try {
            def data = pveGetAt(base, path)
            pveActiveBase = base
            return data
        } catch (IOException failure) {
            def status = pveFailureStatus(failure)
            if (status != null && status < 500) { throw failure }
            last = failure
        }
    }
    throw last ?: new IOException('No Proxmox API address to ask: set pve.api.url')
}
def pveSelfBase = pveHostUrl(pveHostProp('system.hostname'))
def pveWildValue = { value ->
    (value == null ? '' : value.toString()).replaceAll('[^A-Za-z0-9_-]', '-')
}
def pveDisplayName = { value ->
    (value == null ? '' : value.toString()).replaceAll('#', ' ').trim()
}
def pvePropValue = { value ->
    URLEncoder.encode(value == null ? '' : value.toString(), 'UTF-8')
}
def pveDiscover = { String id, String name, String description, Map properties,
                    Map rawProperties = [:] ->
    def pairs = properties
        .findAll { key, value -> value != null && !value.toString().trim().isEmpty() }
        .collect { key, value -> 'auto.' + key + '=' + pvePropValue(value) }
    pairs += rawProperties
        .findAll { key, value -> value != null && !value.toString().trim().isEmpty() }
        .collect { key, value -> key + '=' + pvePropValue(value) }
    println(pveWildValue(id) + '##' + pveDisplayName(name ?: id) + '##' +
            pveDisplayName(description) + '####' + pairs.join('&'))
}
def pveListHidden = { Closure get, String path, String privilege ->
    def rights = get('/access/permissions?path=' + path)
    def held = (rights instanceof Map && rights[path] instanceof Map) ? rights[path][privilege] : null
    held?.toString() != '1'
}
def pveHiddenReason = { String what, String path, String privilege ->
    what + ' came back empty, and the token does not hold ' + privilege + ' on ' + path +
        ' with propagation. Proxmox filters this list by the token\'s ACL rather than refusing it, ' +
        'so the list may only be hidden; discovery stops so the instances are kept. Give the token ' +
        privilege + ' on / with propagation.'
}
def pveBackupInstances = { ->
    def instances = []
    (pveGet('/cluster/backup') ?: []).each { job ->
        def jobId = job.id?.toString()
        if (!jobId) { return }
        def label = job.comment?.toString()?.trim() ?: jobId
        def included = pveGet('/cluster/backup/' + URLEncoder.encode(jobId, 'UTF-8') + '/included_volumes')
        def guests = (included instanceof Map ? included.children : included) ?: []
        guests.each { guest ->
            def type = [qemu: 'qemu', lxc: 'lxc', VM: 'qemu', CT: 'lxc'][guest.type?.toString()]
            if (!type || guest.id == null) { return }
            def vmid = guest.id.toString()
            def volumes = (guest.children ?: []).findAll { it.id != null }
            def isIncluded = { volume -> volume.included?.toString() in ['1', 'true'] }
            def volumeKey = { volume -> volume.id.toString().tokenize(':').last() }
            instances << [
                id      : jobId + '-' + vmid,
                vmid    : vmid,
                name    : guest.name?.toString(),
                type    : type,
                covered : true,
                jobId   : jobId,
                job     : label,
                schedule: job.schedule?.toString(),
                storage : job.storage?.toString(),
                enabled : !(job.enabled?.toString() in ['0', 'false']),
                nextRun : job.'next-run',
                included: volumes.findAll { isIncluded(it) }
                    .collect { volumeKey(it) + ': ' + it.name },
                excluded: volumes.findAll { !isIncluded(it) }
                    .collect { volumeKey(it) + ': ' + it.name + (it.reason ? ' (' + it.reason + ')' : '') }
            ]
        }
    }
    try {
        (pveGet('/cluster/backup-info/not-backed-up') ?: []).each { guest ->
            if (guest.vmid == null) { return }
            def vmid = guest.vmid.toString()
            instances << [id: 'none-' + vmid, vmid: vmid, name: guest.name?.toString(),
                          type: guest.type?.toString(), covered: false, job: 'No backup job']
        }
    } catch (Exception unavailable) {
        System.err.println('Guests covered by no backup job are not listed on this Proxmox ' +
            'version: ' + unavailable.message)
    }
    return instances
}
def pveBackupResults = { List instances, int maxRuns = 50 ->
    def online = (pveGet('/cluster/resources?type=node') ?: [])
        .findAll { it.status?.toString() == 'online' }
        .collect { it.node?.toString() }
        .findAll { it }
    def runs = []
    def complete = true
    online.each { nodeName ->
        try {
            (pveGet('/nodes/' + nodeName + '/tasks?typefilter=vzdump&limit=' + maxRuns) ?: []).each { task ->
                if (task.upid && task.starttime != null) {
                    runs << [node  : nodeName, upid: task.upid.toString(), start: task.starttime as long,
                             end   : task.endtime == null ? null : task.endtime as long,
                             status: task.status?.toString()?.trim()]
                }
            }
        } catch (Exception nodeException) {
            complete = false
            System.err.println('Backup runs not read from node ' + nodeName + ': ' + nodeException.message)
        }
    }
    runs = runs.sort { -it.start }.take(maxRuns)
    def startingLine = ~/^INFO: Starting Backup of VM (\d+)/
    def finishedLine = ~/^INFO: Finished Backup of VM (\d+)/
    def failedLine = ~/^ERROR: Backup of VM (\d+) failed(?: - (.*))?/
    def sizeLine = ~/archive file size: ([\d.]+)\s*([KMGT]?)B/
    def storageOption = ~/--storage\s+(\S+)/
    def excludeOption = ~/--exclude\s+(\S+)/
    def binary = ['': 1d, K: 1024d, M: 1048576d, G: 1073741824d, T: 1099511627776d]
    def sameStorage = { instance, String storage ->
        instance.storage == null || storage == null || storage == instance.storage
    }
    def successes = []
    def failures = []
    def covered = instances.findAll { it.covered }
    def newestSuccess = { instance ->
        successes.find { it.vmid == instance.vmid && sameStorage(instance, it.storage) }
    }
    def guestNodes = null
    for (run in runs) {
        if (covered.every { newestSuccess(it) }) { break }
        def logPath = '/nodes/' + run.node + '/tasks/' + URLEncoder.encode(run.upid, 'UTF-8') + '/log'
        def lines = []
        try {
            int start = 0
            while (true) {
                def page = pveGet(logPath + '?start=' + start + '&limit=1000') ?: []
                lines.addAll(page.collect { it.t?.toString() ?: '' })
                if (page.size() < 1000) { break }
                start += 1000
            }
        } catch (Exception logException) {
            complete = false
            System.err.println('Backup run ' + run.upid + ' not read: ' + logException.message)
            break
        }
        def jobLine = lines.find { it.contains('starting new backup job') }
        def storageMatch = jobLine ? (jobLine =~ storageOption) : null
        def runStorage = storageMatch?.find() ? storageMatch.group(1) : null
        def failure = { String vmid, String reason ->
            [storage: runStorage, vmid: vmid, start: run.start, end: run.end, node: run.node,
             reason : reason?.trim() ?: 'no reason logged']
        }
        String current = null
        Double currentBytes = null
        def reached = [] as Set
        lines.each { line ->
            def starting = line =~ startingLine
            def size = line =~ sizeLine
            def finished = line =~ finishedLine
            def failed = line =~ failedLine
            if (starting.find()) {
                current = starting.group(1)
                currentBytes = null
                reached << current
            } else if (size.find()) {
                currentBytes = (size.group(1) as double) * binary[size.group(2)]
            } else if (finished.find()) {
                reached << finished.group(1)
                successes << [storage: runStorage, vmid: finished.group(1), start: run.start,
                              bytes  : finished.group(1) == current ? currentBytes : null]
            } else if (failed.find()) {
                reached << failed.group(1)
                failures << failure(failed.group(1), failed.group(2))
            }
        }
        def status = run.status
        if (!status || status == 'OK' || status.startsWith('WARNINGS')) { continue }
        def words = jobLine ? jobLine.substring(jobLine.indexOf('vzdump') + 6).trim().tokenize() : []
        def listed = words.takeWhile { it ==~ /\d+/ }
        if (!jobLine) {
            def upidParts = run.upid.split(':', -1)
            def upidGuest = upidParts.size() > 6 ? upidParts[6] : ''
            listed = upidGuest ==~ /\d+/ ? [upidGuest] : []
            def storageNamed = status =~ "storage '([^']+)'"
            runStorage = storageNamed.find() ? storageNamed.group(1) : null
            if (!listed && runStorage == null) {
                System.err.println('Backup run ' + run.upid + ' failed before naming its guests or storage: ' + status)
                continue
            }
        }
        def excludeMatch = jobLine ? (jobLine =~ excludeOption) : null
        def excluded = excludeMatch?.find() ? excludeMatch.group(1).tokenize(',; ') : []
        if (!listed && guestNodes == null) {
            try {
                guestNodes = (pveGet('/cluster/resources?type=vm') ?: [])
                    .collectEntries { [(it.vmid?.toString()): it.node?.toString()] }
            } catch (Exception guestException) {
                complete = false
                System.err.println('Guests of backup run ' + run.upid + ' not found: ' + guestException.message)
                break
            }
        }
        covered.findAll { instance ->
            !reached.contains(instance.vmid) && sameStorage(instance, runStorage) &&
                (listed ? listed.contains(instance.vmid) :
                    guestNodes[instance.vmid] == run.node && !excluded.contains(instance.vmid))
        }.collect { it.vmid }.unique().each { vmid ->
            failures << failure(vmid, status)
        }
    }
    return [complete: complete, successes: successes, failures: failures, sameStorage: sameStorage]
}
def pveBackupState = { Map instance, Map results ->
    def newest = results.successes.find { it.vmid == instance.vmid && results.sameStorage(instance, it.storage) }
    long newestTime = newest ? newest.start as long : 0L
    def failure = results.failures.find { failure ->
        failure.vmid == instance.vmid && results.sameStorage(instance, failure.storage) && failure.start > newestTime
    }
    [newest: newest, failure: failure]
}
